import { useState } from "react";

export function QuickCreate({
  label = "{{label}}",
  placeholder = "{{placeholder}}",
  open: initialOpen = {{open}},
  accent = "{{accent}}",
}) {
  const [open, setOpen] = useState(initialOpen);
  return (
    <div style={{ width: 260, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      {!open && <button type="button" onClick={() => setOpen(true)} style={{ width: "100%", textAlign: "left", border: "1.5px dashed " + accent, background: "transparent", borderRadius: 8, padding: "10px 14px", fontWeight: 600, color: "#241430", cursor: "pointer" }}>{label}</button>}
      {open && (
        <div style={{ borderRadius: 10, border: "1.5px solid " + accent, padding: 10, background: "#FAF7F2" }}>
          <input type="text" placeholder={placeholder} autoFocus style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", borderRadius: 6, border: "1.5px solid #24143033", marginBottom: 8, font: "inherit" }} />
          <div style={{ display: "flex", gap: 6 }}>
            <button type="button" onClick={() => setOpen(false)} style={{ background: accent, border: "none", borderRadius: 6, padding: "7px 14px", fontWeight: 600, cursor: "pointer" }}>Add</button>
            <button type="button" onClick={() => setOpen(false)} style={{ background: "transparent", border: "none", padding: "7px 14px", color: "#241430aa", cursor: "pointer" }}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}
